import os
import requests

def validate_document_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Missing OpenAI API key")

    schema = config.get(
        "schema",
        {
            "type": "object",
            "properties": {
                "is_valid": {"type": "boolean"},
                "missing_fields": {"type": "array", "items": {"type": "string"}},
                "field_confidences": {
                    "type": "object",
                    "additionalProperties": {"type": "number"},
                },
            },
            "required": ["is_valid", "missing_fields", "field_confidences"],
            "additionalProperties": False,
        },
    )

    required_fields = config.get("required_fields", [])
    confidence_threshold = float(config.get("confidence_threshold", 0.8))
    model = config.get("model", "gpt-4o-mini")
    api_url = "https://api.openai.com/v1/responses"

    prompt = {
        "task": "Validate required structured fields and confidence scores for a document extraction payload.",
        "required_fields": required_fields,
        "confidence_threshold": confidence_threshold,
        "payload": payload,
        "instructions": [
            "Return is_valid true only if all required fields are present and every required field confidence is >= confidence_threshold.",
            "List any missing required fields in missing_fields.",
            "For field_confidences, include confidence scores for the required fields when available.",
            "Respond with JSON matching the provided schema.",
        ],
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    data = {
        "model": model,
        "input": [
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": str(prompt)},
                ],
            }
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "document_validation",
                "schema": schema,
                "strict": True,
            }
        },
    }

    response = requests.post(api_url, headers=headers, json=data, timeout=float(config.get("timeout", 30)))
    response.raise_for_status()
    body = response.json()

    result = {}
    for item in body.get("output", []):
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                import json as _json
                result = _json.loads(content.get("text", "{}"))
                break
        if result:
            break

    if not result and "output_text" in body:
        import json as _json
        result = _json.loads(body["output_text"])

    return result
